import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { test } from 'node:test';
import { APP_LANGUAGES } from '../src/settings.ts';

// The files are generated by scripts/city-data/build.mjs (npm run data:cities). These checks keep
// the generated artifacts consistent with each other and with what the browser code expects.
const dataUrl = new URL('../public/data/', import.meta.url);
const readJson = (path) => JSON.parse(readFileSync(new URL(path, dataUrl), 'utf8'));
const search = readJson('cities-search.json');

const compareAliases = (left, right) => (
  left[0] - right[0]
  || left[1].localeCompare(right[1])
  || right[3] - left[3]
  || left[2].localeCompare(right[2])
);

test('search data has the compact tuple format', () => {
  assert.ok(search.cities.length > 60000);
  for (const city of search.cities) {
    assert.equal(city.length, 6);
  }
  for (const alias of search.aliases) {
    assert.equal(alias.length, 4);
  }
});

test('aliases are pre-sorted so the first one per city and language is the display name', () => {
  for (let index = 1; index < search.aliases.length; index += 1) {
    assert.ok(compareAliases(search.aliases[index - 1], search.aliases[index]) <= 0, `aliases out of order at ${index}`);
  }
});

test('per-language city names match the search data', () => {
  const baseNames = new Map(search.cities.map(([id, name]) => [id, name]));
  const expected = new Map(APP_LANGUAGES.map((language) => [language, {}]));
  const seen = new Set();

  for (const [cityId, locale, name] of search.aliases) {
    const key = `${cityId}:${locale}`;

    if (seen.has(key)) {
      continue;
    }

    seen.add(key);

    if (expected.has(locale) && name !== baseNames.get(cityId)) {
      expected.get(locale)[cityId] = name;
    }
  }

  for (const language of APP_LANGUAGES) {
    assert.ok(existsSync(new URL(`city-names/${language}.json`, dataUrl)), `missing city-names/${language}.json`);
    assert.deepEqual(readJson(`city-names/${language}.json`), expected.get(language), language);
  }
});
